function exportPDF() {

    const deleteBtns = Array.from(document.getElementsByClassName('Quote-Grid-Delete-Container')).map((element) => {return element as HTMLElement});
    const inputs = Array.from(document.querySelectorAll('input'));
    const textarea = Array.from(document.querySelectorAll('textarea'));

    document.getElementById('add-line-btn')!.style.display = 'none';
    document.getElementById('generate-btn')!.style.display = 'none';
    document.getElementById('controller-container')!.style.display = 'none';
    document.getElementById('Grid-Bar-Hidden')!.style.display = 'block';

    deleteBtns.forEach((element) => {
        element.style.display = 'none';
    });

    inputs.forEach((element) => {
        element.className += ' App-Skinned';
    });

    textarea.forEach((element) => {
        element.style.height = "";
        element.style.height = element.scrollHeight + "px"
        element.className += ' App-Skinned';

        element.style.display = 'none';

        const node = document.createElement('p');
        node.textContent = element.value;

        node.style.textAlign = element.className.includes('Quote-Grid-Number-Field') ? 'right' : 'left';
        node.style.margin = '0';

        if(element.className.includes('Quote-Grid-Number-Field')) {
            node.style.marginRight = '0.75rem';
        }

        node.style.whiteSpace = 'pre-wrap';
        node.style.wordBreak = 'break-word';


        node.style.fontFamily = 'Arial, serif';
        element.parentElement!.appendChild(node);
    });

    setTimeout(() => {
        window.print();
        document.getElementById('add-line-btn')!.style.display = 'initial';
        document.getElementById('controller-container')!.style.display = 'flex';
        document.getElementById('generate-btn')!.style.display = 'block';
        document.getElementById('Grid-Bar-Hidden')!.style.display = 'none';
        deleteBtns.forEach((element) => {
            element.style.display = 'unset';
        });
        inputs.forEach((element) => {
            element.className = element.className.replace('App-Skinned','');
        });

        textarea.forEach((element) => {
            element.className = element.className.replace('App-Skinned','');
            element.style.display = 'block';
            element.nextElementSibling!.remove();

            element.style.height = "";
            element.style.height = element.scrollHeight + "px"
        });
    }, 800);
};

export default exportPDF;