import React from 'react';
import logo from './../img/logo.png';
import './../App.css';
import { doc, getDoc } from "firebase/firestore"; 
import { db } from "../App";

interface FormElements extends HTMLFormControlsCollection {
    password: HTMLInputElement
}

interface PasswordFormsElement extends HTMLFormElement {
    readonly elements: FormElements
}

interface ILandingProp {
    gotoQuote: () => void;
}
function Landing(props: ILandingProp) {
    const { gotoQuote } = props;
    const PASSWORD = "louka";
    const TIMESTAMPKEY = "timestamp";

    const urlParams = new URLSearchParams(window.location.search);
    const current_id = urlParams.get('id');

    const getDocFirebase = async function(doc_id: string) {
        const docRef = doc(db, "soumissions", doc_id);
        const docSnap = await getDoc(docRef);
        if (docSnap.exists()) {
            window.location = docSnap.data().url.replaceAll('id=', 'oldid=');
        }
    }

    if (current_id) {
        getDocFirebase(current_id ?? '');
    }

    let lastLogin = Number(localStorage.getItem(TIMESTAMPKEY)) ?? 0;
    if(lastLogin >= Date.now() - 21600000  ) {
        gotoQuote();
    }

    const handleSubmit = (e: React.FormEvent<PasswordFormsElement>) => {
        e.preventDefault();
        if(e.currentTarget.elements.password.value === PASSWORD) {
            document.getElementById("App-password")!.className = "App-password";
            
            localStorage.setItem(TIMESTAMPKEY, Date.now().toString());

            gotoQuote();
        } else {
            document.getElementById("App-password")!.className = "App-password";
            setTimeout(() => {
                document.getElementById("App-password")!.className += " App-password--error";
            },50);

        }
    }

    return (
        <div className="App App-Landing">
            <div className="App-header">
                <a
                    className="App-link--header"
                    href="https://www.armoiresbc.ca/"
                    target="_blank"
                    rel="noopener noreferrer"
                >
                    Site web public
                </a>
                <form onSubmit={handleSubmit}>
                    <img src={logo} alt="logo" className="App-Logo" />
                    <p>
                        <label htmlFor="App-password">Mot de passe</label>
                    </p>
                    <p>
                        <input id="App-password" type="password" name="password" className="App-password"/>
                    </p>
                    <input className="App-link" type="submit" value="Ouvrir" />
                </form>
            </div>
        </div>
    );
}

export default Landing;
