import React, {useEffect, useState} from 'react';
import './../App.css';
import './Quote.css';
import logo from "../img/logo_black.png";
import exportShortcut from "../helpers/ExportShortcut";
import exportPDF from "../helpers/ExportPDF";

import { collection, query, limit, orderBy } from "firebase/firestore";
import { db } from "../App";
import { getDocs } from "firebase/firestore";

export interface IGridElement {
    description?: string;
    total?: string;
}

class GridElement implements IGridElement {
    description?: string;
    total?: string;
    constructor(description?: string, total?: string) {
        this.description = description;
        this.total = total;
    }
}

const decode = (str: string):string => { 
    var base64regex = /^([0-9a-zA-Z+/]{4})*(([0-9a-zA-Z+/]{2}==)|([0-9a-zA-Z+/]{3}=))?$/;
    if(base64regex.test(str)) {
        return atob(str);
    }
    return str;
};
const encode = (str: string):string => encodeURIComponent(str);

function Quote() {
    const urlSearch = new URLSearchParams(window.location.search);
    const monthNames = ["Janvier", "Fevrier", "Mars", "Avril", "Mai", "Juin",
        "Juillet", "Aout", "Septembre", "Octobre", "Novembre", "Decembre"
    ];

    let dateDefaultValue = decode(urlSearch.get("quote_date") ?? '');
    if(!dateDefaultValue) {
        dateDefaultValue = `${new Date().getDate()} ${ monthNames[new Date().getMonth()]} ${new Date().getFullYear()}`
    }

    const forDefaultValue = decode(urlSearch.get("quote_for") ?? '');
    const locationDefaultValue = decode(urlSearch.get("quote_location") ?? '');
    const descriptionDefaultValue = decode(urlSearch.get("quote_description") ?? '');
    const acompteDefaultValue = decode(urlSearch.get("quote_acompte") ?? '');

    const descriptionTitleDefaultValue = decode((urlSearch.get("quote_description_title") ?? '') ?? encode('Description des travaux'));
    const titleDefaultValue = decode((urlSearch.get("quote_title") ?? '') ?? encode('Soumission'));
    const costDefaultValue = decode((urlSearch.get("quote_cost_title") ?? '') ?? encode('Description des coûts'));


    let gridDefaultValue = [];
    let index = 0;
    while(urlSearch.get('quote_cost_name_'+index)) {
        const name = urlSearch.get('quote_cost_name_'+ index);
        const cost = urlSearch.get('quote_cost_value_'+ index);
        gridDefaultValue.push(new GridElement(name ? decode(name) : undefined, cost ? decode(cost) : undefined))
        ++index;
    }

    gridDefaultValue.push(new GridElement());
    const getGridLine = (index: number,length: number, gridElement?: IGridElement) => {
        return (<>
                    <tr key={index} className="Quote-Force-Print-Block">
                        <td><textarea onInput={handleOnDescriptionInput} onChange={handleChangeGridDescriptionValue} data-index={index} value={gridElement?.description} name={"quote_cost_name_" + index} id={"quote_cost_name_" + index} className="Quote-Text-Field Quote-Grid-Text-Area" placeholder={"Description des coûts " + (index+1)}/></td>
                        <td className="Quote-Grid-Top-Aligned"><textarea onInput={handleOnDescriptionInput} onChange={handleChangeGridTotalValue} onBlur={appendCashSuffix} data-index={index} value={gridElement?.total} name={"quote_cost_value_" + index} id={"quote_cost_value_" + index} className="Quote-Text-Field Quote-Grid-Number-Field" placeholder="0.00$"></textarea></td>
                        {index !== 0 && (<div className="Quote-Grid-Top-Aligned Quote-Grid-Delete-Container"><button onClick={handleOnDeleteLine} data-index={index} className="Quote-Grid-Delete-Button">X</button></div>)}
                    </tr>
                    {index !== length-1 && (<hr />)}
                </>
        );
    }

    let [gridElements, setGridElements] = useState<IGridElement[]>(gridDefaultValue);

    const handleChangeGridDescriptionValue = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        e.preventDefault();
        const index = Number(e.currentTarget.dataset.index);
        gridElements.at(index)!.description = e.currentTarget.value;

        const clonedElement  = Object.assign([], gridElements);
        setGridElements(clonedElement);
    };
    const appendCashSuffix = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        e.preventDefault();

        let val = e.currentTarget.value;
        val = val.replaceAll('$', '').replace(',', '.');
        e.currentTarget.value = Number(val).toFixed(2).toString() + '$';

        handleChangeGridTotalValue(e);
    }

    const handleBlurAcompte = (e: React.ChangeEvent<HTMLInputElement>) => {
        e.preventDefault();

        const num = stringToNumber(e.currentTarget.value);
        e.currentTarget.value = numberWithSpaces(num) + '$'

        const clonedElement  = Object.assign([], gridElements);
        setGridElements(clonedElement);
    }

    const handleChangeGridTotalValue = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        e.preventDefault();
        const index = Number(e.currentTarget.dataset.index);
        gridElements.at(index)!.total = e.currentTarget.value;

        const clonedElement  = Object.assign([], gridElements);
        setGridElements(clonedElement);
    };

    const handleOnAddLine = (e: React.MouseEvent<HTMLButtonElement>) => {
        e.preventDefault();
        setGridElements(gridElements!.concat(new GridElement()));
    };

    const stringToNumber = (value?: string) => {
        return value ? Number(value.replaceAll('$', '').replaceAll(',', '.').replaceAll(' ', '')) : 0;
    }

    const numberWithSpaces = (x: number) => {
        const parts = x.toFixed(2).toString().split(".");
        parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, " ");
        return parts.join(".");
    }

    const handleOnDeleteLine = (e: React.MouseEvent<HTMLButtonElement>) => {
        e.preventDefault();
        const index = Number(e.currentTarget.dataset.index);

        // Make sure that gridElement contains all its data, so we delete the correct entry
        gridElements.forEach((element, index) => {
            gridElements.at(index)!.description = (document.getElementById('quote_cost_name_' + index) as HTMLInputElement).value;
            gridElements.at(index)!.total = (document.getElementById('quote_cost_value_' + index) as HTMLInputElement).value;
        });

        const clonedElement  = Object.assign([], gridElements);
        clonedElement.splice(index, 1);
        setGridElements(clonedElement);
    };

    const handleOnSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const forValue = (document.getElementById('quote_for')! as HTMLTextAreaElement).value;

        const split = forValue.split(' ');
        let lastName = split.length >= 1 ? split.at(1) : '';

        if(!lastName) {
            lastName = 'Soumission'
        }
        let index = -1
        const indexes = await getDocs(query(collection(db, "soumissions"), orderBy("index", "desc"), limit(1)));
    
        indexes.forEach((doc) => {
            index = doc.data().index ?? 0;
        });
        const fileName = `${index} ${lastName} - ${new Date().getDate()} ${ monthNames[new Date().getMonth()]} ${new Date().getFullYear()}`;
        document.title = fileName;
        
        window.onafterprint = () => {
            exportShortcut(fileName + '.html', index, gridElements);
            window.onafterprint = null;
        }

        exportPDF();
    };

    const handleOnDescriptionInput = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        e.currentTarget.style.height = "";
        e.currentTarget.style.height = e.currentTarget.scrollHeight + "px"
    };

    const gridComponents = gridElements!.map((element, index) => {
        return getGridLine(index, gridElements.length, element);
    });

    const subTotal = Math.round((gridElements.reduce((sum, current) =>
        sum + (stringToNumber(current.total)), 0)+ Number.EPSILON) * 100) / 100;

    const tps = Math.round(((subTotal *  0.05 ) + Number.EPSILON) * 100) / 100;
    const tvq = Math.round(((subTotal * 0.09975) + Number.EPSILON) * 100) /100;

    let acompte = 0;
    if(document.getElementById('quote_acompte')) {
        acompte = stringToNumber((document.getElementById('quote_acompte')! as HTMLInputElement).value);
    }

    const totalBeforeAccount = Math.round((((subTotal + tps + tvq)) + Number.EPSILON) * 100) /100;
    const total = Math.round((((subTotal + tps + tvq) - acompte) + Number.EPSILON) * 100) /100;

    useEffect(() => {
        setTimeout(() => {
            const textAreas = document.querySelectorAll('textarea');
            textAreas.forEach((textarea) => {
                if(textarea.defaultValue) {
                    textarea.style.height = "";
                    textarea.style.height = textarea.scrollHeight + "px"
                }
            });
        },50);
    }, []);

    return (
        <div className="App Quote-Container" id="Quote-Container">
            <div className="Controller-Container" id="controller-container">
                <button className="Quote-Grid-Add-Button Quote-Grid-Add-Button-Special" onClick={
                    (e) => {
                        e.preventDefault();
                        document.dispatchEvent(new KeyboardEvent('keydown', {'key': 'z', 'ctrlKey': true}));
                        document.dispatchEvent(new KeyboardEvent('keydown', {'key': 'z', 'metaKey': true}));
                        document.execCommand('undo');
                    }}>Annuler</button>
                <button className="Quote-Grid-Add-Button Quote-Grid-Add-Button-Special" onClick={
                    (e) => {
                        e.preventDefault();
                        document.dispatchEvent(new KeyboardEvent('keydown', {'key': 'y', 'ctrlKey': true}));
                        document.dispatchEvent(new KeyboardEvent('keydown', {'key': 'y', 'metaKey': true}));
                        document.execCommand('redo');
                    }}>Refaire</button>
            </div>
            <form onSubmit={handleOnSubmit}>
                <div className="Quote-Header-Container">
                    <div className="Quote-Header-Logo">
                        <img src={logo} alt="logo" />
                    </div>
                    <div className="Quote-Header-Date">
                        <input defaultValue={dateDefaultValue} name="quote_date" id="quote_date" className="Quote-Text-Field" type="text" placeholder={"Date"} />
                    </div>
                </div>
                <div className="Quote-Spec-Container">
                    <div className="Quote-Text">
                        <b>Contact:</b> Benoît Charron
                        <br/>
                        <b>Adresse:</b> 766, rue Caya,
                        <br/>
                        &emsp;&emsp;&emsp;&emsp;&nbsp;&nbsp;Saint-Colomban,
                        <br/>
                        &emsp;&emsp;&emsp;&emsp;&nbsp;&nbsp;Qc, J5K 1R7
                    </div>
                    <div className="Quote-Text">
                        <b>Bureau:</b> 450.530.5588
                        <br/>
                        <b>Email:</b> armoiresbc@gmail.com
                        <br/>
                        <b>Site web:</b> https://www.armoiresbc.ca
                    </div>
                </div>
                <div>
                    <p>
                        <b className="Quote-Underline Quote-Label"><input type="text" id="quote_title" name="quote_title" className="Quote-Transparent-Input" defaultValue={titleDefaultValue} /></b>
                    </p>
                </div>
                <div className="Quote-For-Container">
                    <div className="Quote-For-Inner-Container">
                        <label className="Quote-Text-Area-Label" htmlFor="quote_for" id="for_label">Soumission pour: </label> <textarea defaultValue={forDefaultValue} name="quote_for" id="quote_for" className="Quote-Text-Field Quote-Text-Field--Area" placeholder="Nom du client" />
                    </div>
                    <div className="Quote-For-Inner-Container">
                        <label className="Quote-Text-Area-Label" htmlFor="quote_location">Lieu: </label> <textarea defaultValue={locationDefaultValue} name="quote_location" id="quote_location" className="Quote-Text-Field Quote-Text-Field--Area" placeholder="Lieu" />
                    </div>
                </div>
                <div>
                    <p>
                        <b className="Quote-Underline Quote-Label"><input type="text" id="quote_description_title" name="quote_description_title" className="Quote-Transparent-Input" defaultValue={descriptionTitleDefaultValue} /></b>
                    </p>
                </div>
                <div className="Quote-Force-Print-Block">
                    <textarea defaultValue={descriptionDefaultValue} onInput={handleOnDescriptionInput} name="quote_description" id="quote_description" placeholder="Description des travaux" className="Quote-Text-Field Quote-Text-Field--Area Quote-Text-Field--Area--extra" />
                </div>
                <div>
                    <p>
                        <b className="Quote-Underline Quote-Label"><input type="text" id="quote_cost_title" name="quote_cost_title" className="Quote-Transparent-Input" defaultValue={costDefaultValue} /></b>
                    </p>
                </div>
                <table className="Quote-Grid-Polyfill">
                    <thead>
                        <tr>
                            <th scope="col" style={{width: "85%"}}>Description</th>
                            <th scope="col" style={{width: "20%"}}>Total</th>
                        </tr>
                    </thead>
                    <tbody>
                        {gridComponents}
                    </tbody>
                </table>
                <hr className="Grid-Bar-Hidden" id="Grid-Bar-Hidden"/>
                <button id="add-line-btn" className="Quote-Grid-Add-Button Quote-Grid-Add-Button-Special" onClick={handleOnAddLine}>Ajouter une ligne</button>
                <div className="Grid-Form-Container">
                    <div className="Quote-Entreprise-Spec">
                        <div className="Quote-Text">
                            <b>No. d'entreprise (NEQ):</b><br /><span className="Quote-Text-Value">2248433973</span>
                        </div>
                        <div className="Quote-Text">
                            <b>RBQ:</b><br /><span className="Quote-Text-Value">5611-4630-01</span>
                            <br />
                            <b>APCHQ:</b><br /> <span className="Quote-Text-Value">208385 04 2000</span>
                        </div>
                    </div>
                    < hr />
                    <div className="Result-Container">
                        <div className="Quote-Grid-Footer-Layout">
                            <div className="Quote-Grid-Static-Headers">Sous-Total</div>
                            <div className="Quote-Grid-Table-Value" >{(Number.isNaN(subTotal) ? 'N/A' : numberWithSpaces(subTotal)) + ' $'}</div>
                        </div>

                        <div className="Quote-Grid-Footer-Layout">
                            <div className="Quote-Grid-Static-Headers">TPS 5% <span className="Quote-Text-Value-Special">(81816 8460 RT0001)</span></div>
                            <div className="Quote-Grid-Table-Value">{(Number.isNaN(tps) ? 'N/A' : numberWithSpaces(tps)) + ' $'}</div>
                        </div>
                        <div className="Quote-Grid-Footer-Layout">
                            <div className="Quote-Grid-Static-Headers">TVQ 9.975% <span className="Quote-Text-Value-Special">(1078558772)</span></div>
                            <div className="Quote-Grid-Table-Value">{(Number.isNaN(tvq) ? 'N/A' : numberWithSpaces(tvq)) + ' $'}</div>
                        </div>
                        <div className="Quote-Grid-Footer-Layout">
                            <div className="Quote-Grid-Static-Headers">Total</div>
                            <div className="Quote-Grid-Table-Value">{(Number.isNaN(totalBeforeAccount) ? 'N/A' : numberWithSpaces(totalBeforeAccount)) + ' $'}</div>
                        </div>
                        <div className="Quote-Grid-Footer-Layout">
                            <div className="Quote-Grid-Static-Headers">Acompte versé</div>
                            <div className="Quote-Grid-Table-Value"><input onBlur={handleBlurAcompte} type="text" id="quote_acompte" name="quote_acompte" className="Quote-Transparent-Input Quote-Transparent-Input--small Quote-Grid-Table-Value Quote-Grid-Table-Value-Input" defaultValue={acompteDefaultValue} /></div>
                        </div>
                        <div className="Quote-Grid-Footer-Layout">
                            <div className="Quote-Grid-Static-Headers">Solde dû</div>
                            <div className="Quote-Grid-Table-Value">{(Number.isNaN(total) ? 'N/A' : numberWithSpaces(total)) + ' $'}</div>
                        </div>
                    </div>
                </div>
                <div id="generate-btn" className="Quote-Generate-Button">
                    <button className="Quote-Grid-Add-Button">Générer la soumission</button>
                </div>
            </form>
        </div>
    );
}

export default Quote;
