import {IGridElement} from "../views/Quote";
import { doc, setDoc } from "firebase/firestore"; 
import { db } from "../App";

const encode = (str: string):string =>encodeURIComponent(str);

const escapeHtml = (str: string): string =>
    str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

async function permissionsCheck() {
    return navigator.permissions.query({ name: "clipboard-write" as PermissionName });
}

async function exportShortcut(fileName: string, lastIndex: number, elements: IGridElement[]) {
    //Generate URL
    const dateValue = encode((document.getElementById('quote_date')! as HTMLInputElement).value ?? '');
    const forValue = encode((document.getElementById('quote_for')! as HTMLTextAreaElement).value ?? '');
    const locationValue = encode((document.getElementById('quote_location')! as HTMLTextAreaElement).value ?? '');
    const descriptionValue = encode((document.getElementById('quote_description')! as HTMLTextAreaElement).value ?? '');
    const acompteValue = encode((document.getElementById('quote_acompte')! as HTMLInputElement).value ?? '');

    const descriptionTitleValue = encode((document.getElementById('quote_description_title')! as HTMLInputElement).value ?? '');
    const costTitleValue = encode((document.getElementById('quote_cost_title')! as HTMLInputElement).value ?? '');

    const titleValue = encode((document.getElementById('quote_title')! as HTMLInputElement).value ?? '');

    let shortCutURL = window.location.protocol + '//' + window.location.host + `?quote_date=${dateValue}&quote_for=${forValue}&quote_location=${locationValue}&quote_description=${descriptionValue}&quote_title=${titleValue}&quote_description_title=${descriptionTitleValue}&quote_cost_title=${costTitleValue}&quote_acompte=${acompteValue}`;
    elements.forEach((element, index) => {
        shortCutURL += `&quote_cost_name_${index}=${encode(element.description ?? '')}&quote_cost_value_${index}=${encode(element.total ?? '')}`;
    });

    const hasPermissions = await permissionsCheck();
    if (hasPermissions && document.hasFocus()) {
        await navigator.clipboard.writeText(shortCutURL);
    }
    
    const id = Date.now().toString(36);


    // Save in firebase
    await setDoc(doc(db, "soumissions", id), {
        url: shortCutURL,
        index: lastIndex + 1,
    });

    // Generate URL 
    // An HTML redirect page opens with a double-click in any browser/OS; browsers rename .url downloads to .download
    const targetUrl = window.location.origin + '?id=' + id;
    const fileData = `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<meta http-equiv="refresh" content="0; url=${targetUrl}">
<title>${escapeHtml(fileName)}</title>
</head>
<body>
<p>Redirection en cours... <a href="${targetUrl}">Cliquez ici si la page ne s'ouvre pas.</a></p>
<script>window.location.replace(${JSON.stringify(targetUrl)});</script>
</body>
</html>`;
    const blob = new Blob([fileData], { type: "text/html" });
    const url = URL.createObjectURL(blob);

    const link = document.createElement("a");
    link.download = fileName;
    link.href = url;
    link.click();
    link.remove();
};

export default exportShortcut;